#include "rf2o_laser_odometry/PlanarTwist.hpp"
#include <iostream>
#include <limits>

void near(double actual, double expected) {
  if (std::abs(actual-expected)>1e-8) throw std::runtime_error("Twist mismatch");
}
int main() {
  try {
    auto forward=rf2o::planarTwist(.02,0,0,.1);
    near(forward.x,.2); near(forward.y,0);
    auto sideways=rf2o::planarTwist(0,-.03,0,.1);
    near(sideways.x,0); near(sideways.y,-.3);
    auto rotation=rf2o::planarTwist(0,0,.05,.1);
    near(rotation.x,0); near(rotation.y,0); near(rotation.yaw,.5);
    // Translation generated by a constant combined body twist.
    double theta=.08, dt=.2, vx=.3, vy=-.1;
    double a=std::sin(theta)/theta, b=(1-std::cos(theta))/theta;
    auto combined=rf2o::planarTwist(dt*(a*vx-b*vy),dt*(b*vx+a*vy),theta,dt);
    near(combined.x,vx);near(combined.y,vy);near(combined.yaw,theta/dt);
    for(double invalid : {0.0,-.1,std::numeric_limits<double>::quiet_NaN()}) {
      bool rejected=false;
      try { rf2o::planarTwist(0,0,0,invalid); }
      catch(const std::invalid_argument&) { rejected=true; }
      if(!rejected) throw std::runtime_error("Invalid dt accepted");
    }
    std::cout<<"PASS: forward, lateral, rotation, combined SE2 twist, invalid intervals\n";
    return 0;
  } catch(const std::exception& error) { std::cerr<<error.what()<<'\n'; return 1; }
}
